 13→func init() {
 14→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "cursor-cli" {
 15→		return
 16→	}
 17→	Register(&CursorCLI{})
 18→}
 19→
 20→// CursorCLI implements the E2E Agent interface for the Cursor Agent CLI binary.
 21→// The CLI binary is called "agent" and uses Cursor's hooks system via
 22→// .cursor/hooks.json. It maps to the same Entire agent as Cursor IDE ("cursor").
 23→//
 24→// All E2E interactions use interactive (tmux) mode so that the full hook
 25→// lifecycle fires (sessionStart, beforeSubmitPrompt, stop, sessionEnd).
 26→// Headless (-p) mode skips beforeSubmitPrompt and stop hooks.
 27→type CursorCLI struct{}
 28→
 29→func (a *CursorCLI) Name() string               { return "cursor-cli" }
 30→func (a *CursorCLI) Binary() string             { return "agent" }
 31→func (a *CursorCLI) EntireAgent() string        { return "cursor" }
 32→func (a *CursorCLI) TimeoutMultiplier() float64 { return 1.5 }
 33→
 34→// PromptPattern returns a regex matching the Cursor CLI's TUI input prompt.
 35→// The CLI shows a styled input box with placeholder text when ready for input.
 36→func (a *CursorCLI) PromptPattern() string { return `/ commands` }
 37→
 38→func (a *CursorCLI) IsTransientError(out Output, err error) bool {
 39→	if err == nil {
 40→		return false
 41→	}
 42→	if errors.Is(err, context.DeadlineExceeded) {
 43→		return true
 44→	}
 45→	combined := out.Stdout + out.Stderr
 46→	for _, p := range []string{
 47→		"overloaded",
 48→		"rate limit",
 49→		"429",
 50→		"503",
 51→		"529",
 52→		"ECONNRESET",
 53→		"ETIMEDOUT",
 54→		"server error",
 55→		"Internal Server Error",
 56→	} {
 57→		if strings.Contains(combined, p) {
 58→			return true
 59→		}
 60→	}
 61→	return false
 62→}
 63→
 64→func (a *CursorCLI) Bootstrap() error {
 65→	// The Cursor CLI authenticates via CURSOR_API_KEY env var or OAuth.
 66→	// On CI, ensure CURSOR_API_KEY is set. Locally, OAuth/keychain works.
 67→	if os.Getenv("CI") != "" && os.Getenv("CURSOR_API_KEY") == "" {
 68→		return errors.New("CURSOR_API_KEY must be set on CI for cursor-cli E2E tests")
 69→	}
 70→	return nil
 71→}
 72→
 73→func (a *CursorCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 74→	cfg := &runConfig{}
 75→	for _, o := range opts {
 76→		o(cfg)
 77→	}
 78→
 79→	timeout := 90 * time.Second
 80→	if cfg.PromptTimeout > 0 {
 81→		timeout = cfg.PromptTimeout
 82→	}
 83→
 84→	displayCmd := a.Binary() + " --force --workspace " + dir + " (interactive prompt: " + prompt + ")"
 85→
 86→	// Start an interactive tmux session so all hooks fire
 87→	// (beforeSubmitPrompt and stop don't fire in headless -p mode).
 88→	s, err := a.startInteractiveSession(dir)
 89→	if err != nil {
 90→		return Output{Command: displayCmd, ExitCode: -1},
 91→			fmt.Errorf("start interactive session: %w", err)
 92→	}
 93→	defer s.Close()
 94→
 95→	// Wait for trust dialog and accept it.
 96→	if err := a.acceptTrustDialogIfNeeded(s); err != nil {
 97→		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1}, err
 98→	}
 99→
100→	// Wait for the TUI to be ready.
101→	if _, err := s.WaitFor(a.PromptPattern(), 30*time.Second); err != nil {
102→		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
103→			fmt.Errorf("waiting for startup prompt: %w", err)
104→	}
105→
106→	// Send the prompt.
107→	if err := s.Send(prompt); err != nil {
108→		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
109→			fmt.Errorf("sending prompt: %w", err)
110→	}
111→
112→	// Wait for the prompt pattern to reappear (agent finished processing).
113→	content, waitErr := s.WaitFor(a.PromptPattern(), timeout)
114→	if waitErr != nil {
115→		// Check for deadline exceeded to allow transient error detection.
116→		if ctx.Err() == context.DeadlineExceeded {
117→			waitErr = fmt.Errorf("%w: %w", waitErr, context.DeadlineExceeded)
118→		}
119→		return Output{Command: displayCmd, Stdout: content, ExitCode: -1}, waitErr
120→	}
121→
122→	return Output{Command: displayCmd, Stdout: content, ExitCode: 0}, nil
123→}
124→
125→func (a *CursorCLI) StartSession(ctx context.Context, dir string) (Session, error) {
126→	s, err := a.startInteractiveSession(dir)
127→	if err != nil {
128→		return nil, err
129→	}
130→
131→	if err := a.acceptTrustDialogIfNeeded(s); err != nil {
132→		_ = s.Close()
133→		return nil, err
134→	}
135→
136→	// Wait for the TUI to be ready (input prompt).
137→	if _, err := s.WaitFor(a.PromptPattern(), 30*time.Second); err != nil {
138→		_ = s.Close()
139→		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
140→	}
141→	s.stableAtSend = ""
142→
143→	return s, nil
144→}
145→
146→// startInteractiveSession creates a new tmux session running the Cursor CLI
147→// in interactive mode (no -p flag) so all hooks fire.
148→func (a *CursorCLI) startInteractiveSession(dir string) (*TmuxSession, error) {
149→	// Resolve to absolute path so tmux can find the binary even if its
150→	// shell doesn't inherit the test process's PATH (common on CI).
151→	bin, err := exec.LookPath(a.Binary())
152→	if err != nil {
153→		return nil, fmt.Errorf("agent binary not found: %w", err)
154→	}
155→
156→	// Build env-wrapped command so the tmux session inherits critical env vars.
157→	// tmux starts a new shell that doesn't inherit Go's os.Environ().
158→	var envArgs []string
159→	for _, key := range []string{"CURSOR_API_KEY", "PATH", "HOME", "TERM"} {
160→		if v := os.Getenv(key); v != "" {
161→			envArgs = append(envArgs, key+"="+v)
162→		}
163→	}
164→
165→	args := append([]string{"env"}, envArgs...)
166→	args = append(args, bin, "--force", "--workspace", dir)
167→
168→	name := fmt.Sprintf("cursor-cli-test-%d", time.Now().UnixNano())
169→	unset := []string{"CI"}
170→	return NewTmuxSession(name, dir, unset, args[0], args[1:]...)
171→}
172→
173→// acceptTrustDialogIfNeeded checks whether the workspace trust dialog appears
174→// and presses "a" to accept it. The dialog only shows on the first launch in
175→// a workspace — subsequent sessions in the same directory skip it.
176→func (a *CursorCLI) acceptTrustDialogIfNeeded(s *TmuxSession) error {
177→	// Race: either the trust dialog or the input prompt will appear first.
178→	// Use a short timeout to check for the trust dialog without blocking
179→	// too long if the workspace is already trusted.
180→	content, err := s.WaitFor(`Trust this workspace|`+a.PromptPattern(), 30*time.Second)
181→	if err != nil {
182→		return fmt.Errorf("waiting for trust dialog or prompt: %w", err)
183→	}
184→	if strings.Contains(content, "Trust this workspace") {
185→		if err := s.SendKeys("a"); err != nil {
186→			return fmt.Errorf("accepting trust dialog: %w", err)
187→		}
188→	}
189→	return nil
190→}
