 83→// ClearHooksDirCache clears the cached hooks directory.
 84→// This is primarily useful for testing when changing directories.
 85→func ClearHooksDirCache() {
 86→	hooksDirMu.Lock()
 87→	hooksDirCache = ""
 88→	hooksDirCacheDir = ""
 89→	hooksDirMu.Unlock()
 90→}
