205→// InstallGitHook installs generic git hooks that delegate to `entire hook` commands.
206→// These hooks work with any strategy - the strategy is determined at runtime.
207→// If silent is true, no output is printed (except backup notifications, which always print).
208→// localDev controls whether hooks use "go run" (true) or the "entire" binary (false).
209→// absolutePath embeds the full binary path in hooks for GUI git clients.
210→// Returns the number of hooks that were installed (0 if all already up to date).
211→func InstallGitHook(ctx context.Context, silent, localDev, absolutePath bool) (int, error) {
212→	hooksDir, err := GetHooksDir(ctx)
213→	if err != nil {
214→		return 0, err
215→	}
216→
217→	if err := os.MkdirAll(hooksDir, 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
218→		return 0, fmt.Errorf("failed to create hooks directory: %w", err)
219→	}
220→
221→	cmdPrefix, err := hookCmdPrefix(localDev, absolutePath)
222→	if err != nil {
223→		return 0, err
224→	}
225→	specs := buildHookSpecs(cmdPrefix)
226→	installedCount := 0
227→
228→	for _, spec := range specs {
229→		hookPath := filepath.Join(hooksDir, spec.name)
230→		backupPath := hookPath + backupSuffix
231→		backupExists := fileExists(backupPath)
232→
233→		// Back up existing non-Entire hooks
234→		existing, existingErr := os.ReadFile(hookPath) //nolint:gosec // path is controlled
235→		if existingErr == nil && !strings.Contains(string(existing), entireHookMarker) {
236→			if !backupExists {
237→				if err := os.Rename(hookPath, backupPath); err != nil {
238→					return installedCount, fmt.Errorf("failed to back up %s: %w", spec.name, err)
239→				}
240→				fmt.Fprintf(os.Stderr, "[entire] Backed up existing %s to %s%s\n", spec.name, spec.name, backupSuffix)
241→			} else {
242→				fmt.Fprintf(os.Stderr, "[entire] Warning: replacing %s (backup %s%s already exists from a previous install)\n", spec.name, spec.name, backupSuffix)
243→			}
244→			backupExists = true
245→		}
246→
247→		// Chain to backup if one exists
248→		content := spec.content
249→		if backupExists {
250→			content = generateChainedContent(spec.content, spec.name)
251→		}
252→
253→		written, err := writeHookFile(hookPath, content)
254→		if err != nil {
255→			return installedCount, fmt.Errorf("failed to install %s hook: %w", spec.name, err)
256→		}
257→		if written {
258→			installedCount++
259→		}
260→	}
261→
262→	if !silent {
263→		fmt.Println("✓ Installed git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
264→		fmt.Println("  Hooks delegate to the current strategy at runtime")
265→	}
266→
267→	return installedCount, nil
268→}
269→
270→// writeHookFile writes a hook file if it doesn't exist or has different content.
271→// Returns true if the file was written, false if it already had the same content.
272→func writeHookFile(path, content string) (bool, error) {
273→	// Check if file already exists with same content
274→	existing, err := os.ReadFile(path) //nolint:gosec // path is controlled
275→	if err == nil && string(existing) == content {
276→		return false, nil // Already up to date
277→	}
278→
279→	// Git hooks must be executable (0o755)
280→	if err := os.WriteFile(path, []byte(content), 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
281→		return false, fmt.Errorf("failed to write hook file %s: %w", path, err)
282→	}
283→	return true, nil
284→}
285→
286→// RemoveGitHook removes all Entire CLI git hooks from the repository.
287→// If a .pre-entire backup exists, it is restored.
288→// Returns the number of hooks removed.
289→func RemoveGitHook(ctx context.Context) (int, error) {
290→	hooksDir, err := GetHooksDir(ctx)
291→	if err != nil {
292→		return 0, err
293→	}
294→
295→	removed := 0
296→	var removeErrors []string
297→
298→	for _, hook := range gitHookNames {
299→		hookPath := filepath.Join(hooksDir, hook)
300→		backupPath := hookPath + backupSuffix
301→
302→		// Remove the hook if it contains our marker
303→		data, err := os.ReadFile(hookPath) //nolint:gosec // path is controlled
304→		hookIsOurs := err == nil && strings.Contains(string(data), entireHookMarker)
305→		hookExists := err == nil
306→
307→		if hookIsOurs {
308→			if err := os.Remove(hookPath); err != nil {
309→				removeErrors = append(removeErrors, fmt.Sprintf("%s: %v", hook, err))
310→				continue
311→			}
312→			removed++
313→		}
314→
315→		// Restore .pre-entire backup if it exists
316→		if fileExists(backupPath) {
317→			if hookExists && !hookIsOurs {
318→				// A non-Entire hook is present — don't overwrite it with the backup
319→				fmt.Fprintf(os.Stderr, "[entire] Warning: %s was modified since install; backup %s%s left in place\n", hook, hook, backupSuffix)
320→			} else {
321→				if err := os.Rename(backupPath, hookPath); err != nil {
322→					removeErrors = append(removeErrors, fmt.Sprintf("restore %s%s: %v", hook, backupSuffix, err))
323→				}
324→			}
325→		}
326→	}
327→
328→	if len(removeErrors) > 0 {
329→		return removed, fmt.Errorf("failed to remove hooks: %s", strings.Join(removeErrors, "; "))
330→	}
331→	return removed, nil
332→}
333→
334→// generateChainedContent appends a chain call to the base hook content,
335→// so the pre-existing hook (backed up to .pre-entire) is called after our hook.
336→func generateChainedContent(baseContent, hookName string) string {
337→	return baseContent + fmt.Sprintf(`%s
338→_entire_hook_dir="$(dirname "$0")"
339→if [ -x "$_entire_hook_dir/%s%s" ]; then
340→    "$_entire_hook_dir/%s%s" "$@"
341→fi
342→`, chainComment, hookName, backupSuffix, hookName, backupSuffix)
343→}
344→
345→// hookCmdPrefix returns the command prefix for hook scripts and warning messages.
346→// Returns "go run ./cmd/entire/main.go" when local_dev is enabled.
347→// When absolutePath is true, resolves the full binary path via os.Executable()
348→// and returns an error if resolution fails. This is needed for GUI git clients
349→// (Xcode, Tower, etc.) that don't source shell profiles.
350→func hookCmdPrefix(localDev, absolutePath bool) (string, error) {
351→	if localDev {
352→		return "go run ./cmd/entire/main.go", nil
353→	}
354→	if absolutePath {
355→		exe, err := os.Executable()
356→		if err != nil {
357→			return "", fmt.Errorf("--absolute-git-hook-path: failed to resolve binary path: %w", err)
358→		}
359→		resolved, err := filepath.EvalSymlinks(exe)
360→		if err != nil {
361→			return "", fmt.Errorf("--absolute-git-hook-path: failed to resolve symlinks for %s: %w", exe, err)
362→		}
363→		return shellQuote(resolved), nil
364→	}
365→	return "entire", nil
366→}
367→
368→// shellQuote wraps a string in single quotes for safe use in #!/bin/sh scripts.
369→// Handles paths containing spaces, apostrophes, or other shell metacharacters
370→// (e.g., /Users/John O'Brien/bin/entire).
371→func shellQuote(s string) string {
372→	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
373→}
374→
375→// hookSettingsFromConfig loads hook-related settings from .entire/settings.json.
376→// Returns (localDev, absoluteHookPath). On error, both default to false.
377→func hookSettingsFromConfig(ctx context.Context) (localDev, absoluteHookPath bool) {
378→	s, err := settings.Load(ctx)
379→	if err != nil {
380→		return false, false
381→	}
382→	return s.LocalDev, s.AbsoluteGitHookPath
383→}
