200→// UninstallHooks removes Entire hooks from Cursor HooksFileName.
201→// Unknown top-level fields and hook types are preserved on round-trip.
202→func (c *CursorAgent) UninstallHooks(ctx context.Context) error {
203→	worktreeRoot, err := paths.WorktreeRoot(ctx)
204→	if err != nil {
205→		worktreeRoot = "."
206→	}
207→	hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
208→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
209→	if err != nil {
210→		return nil //nolint:nilerr // No hooks file means nothing to uninstall
211→	}
212→
213→	var rawFile map[string]json.RawMessage
214→	if err := json.Unmarshal(data, &rawFile); err != nil {
215→		return fmt.Errorf("failed to parse "+HooksFileName+": %w", err)
216→	}
217→
218→	var rawHooks map[string]json.RawMessage
219→	if hooksRaw, ok := rawFile["hooks"]; ok {
220→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
221→			return fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
222→		}
223→	}
224→	if rawHooks == nil {
225→		rawHooks = make(map[string]json.RawMessage)
226→	}
227→
228→	// Parse only the hook types we manage
229→	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
230→	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
231→	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
232→	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
233→	parseCursorHookType(rawHooks, "stop", &stop)
234→	parseCursorHookType(rawHooks, "preCompact", &preCompact)
235→	parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
236→	parseCursorHookType(rawHooks, "subagentStop", &subagentStop)
237→
238→	// Remove Entire hooks from all hook types
239→	sessionStart = removeEntireHooks(sessionStart)
240→	sessionEnd = removeEntireHooks(sessionEnd)
241→	beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
242→	stop = removeEntireHooks(stop)
243→	preCompact = removeEntireHooks(preCompact)
244→	subagentStart = removeEntireHooks(subagentStart)
245→	subagentStop = removeEntireHooks(subagentStop)
246→
247→	// Marshal modified hook types back into rawHooks
248→	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
249→	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
250→	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
251→	marshalCursorHookType(rawHooks, "stop", stop)
252→	marshalCursorHookType(rawHooks, "preCompact", preCompact)
253→	marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
254→	marshalCursorHookType(rawHooks, "subagentStop", subagentStop)
255→
256→	// Marshal hooks back (preserving unknown hook types)
257→	if len(rawHooks) > 0 {
258→		hooksJSON, err := json.Marshal(rawHooks)
259→		if err != nil {
260→			return fmt.Errorf("failed to marshal hooks: %w", err)
261→		}
262→		rawFile["hooks"] = hooksJSON
263→	} else {
264→		delete(rawFile, "hooks")
265→	}
266→
267→	// Write back
268→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
269→	if err != nil {
270→		return fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
271→	}
272→
273→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
274→		return fmt.Errorf("failed to write "+HooksFileName+": %w", err)
275→	}
276→
277→	return nil
278→}
