 16→func TestResolveTranscriptPath_FileExists(t *testing.T) {
 17→	t.Parallel()
 18→
 19→	// When the transcript file exists at the stored path, resolveTranscriptPath
 20→	// should return that path unchanged.
 21→	tmpDir := t.TempDir()
 22→	transcriptFile := filepath.Join(tmpDir, "session-123.jsonl")
 23→	if err := os.WriteFile(transcriptFile, []byte(`{"test":true}`), 0o600); err != nil {
 24→		t.Fatalf("failed to write test file: %v", err)
 25→	}
 26→
 27→	state := &session.State{
 28→		TranscriptPath: transcriptFile,
 29→		AgentType:      agent.AgentTypeCursor,
 30→	}
 31→
 32→	resolved, err := resolveTranscriptPath(state)
 33→	if err != nil {
 34→		t.Fatalf("resolveTranscriptPath() error = %v", err)
