 44→func TestResolveTranscriptPath_ReResolvesToNestedLayout(t *testing.T) {
 45→	t.Parallel()
 46→
 47→	// Simulates Cursor CLI relocating a transcript mid-session:
 48→	// Stored path (flat):  <dir>/<uuid>.jsonl  (does not exist)
 49→	// Actual path (nested): <dir>/<uuid>/<uuid>.jsonl  (exists)
 50→	tmpDir := t.TempDir()
