 56→	agentSessionID := "87874108-eff2-47a0-b260-183961dd6cb0"
 57→	flatPath := filepath.Join(sessionDir, agentSessionID+".jsonl")
 58→
 59→	// Create the file at the nested path only
 60→	nestedDir := filepath.Join(sessionDir, agentSessionID)
 61→	if err := os.MkdirAll(nestedDir, 0o750); err != nil {
 62→		t.Fatalf("failed to create nested dir: %v", err)
 63→	}
 64→	nestedPath := filepath.Join(nestedDir, agentSessionID+".jsonl")
 65→	if err := os.WriteFile(nestedPath, []byte(`{"role":"user"}`), 0o600); err != nil {
 66→		t.Fatalf("failed to write nested transcript: %v", err)
 67→	}
 68→
 69→	state := &session.State{
 70→		TranscriptPath: flatPath,
 71→		AgentType:      agent.AgentTypeCursor,
 72→	}
 73→
 74→	resolved, err := resolveTranscriptPath(state)
 75→	if err != nil {
 76→		t.Fatalf("resolveTranscriptPath() error = %v", err)
 77→	}
 78→	if resolved != nestedPath {
 79→		t.Errorf("resolveTranscriptPath() = %q, want %q", resolved, nestedPath)
 80→	}
 81→	// State should be updated to the resolved path
 82→	if state.TranscriptPath != nestedPath {
 83→		t.Errorf("state.TranscriptPath = %q, want %q", state.TranscriptPath, nestedPath)
 84→	}
 85→}
